[CmdletBinding()]param([Parameter(Mandatory=$true)][string]$RuntimeDir,[ValidateSet('off','daily','weekly')][string]$Schedule='daily')
$ErrorActionPreference='Stop';$RuntimeDir=[IO.Path]::GetFullPath($RuntimeDir);$task='LocalDeck Database Backup';if($Schedule-eq'off'){schtasks.exe /Delete /TN $task /F 2>$null|Out-Null;exit 0};$automation=Join-Path $RuntimeDir 'automation';New-Item -ItemType Directory -Force $automation|Out-Null;Copy-Item (Join-Path $PSScriptRoot 'run-backups.ps1') $automation -Force;Copy-Item (Join-Path $PSScriptRoot 'Run-LocalDeck-Backups.vbs') $automation -Force;$vbs=Join-Path $automation 'Run-LocalDeck-Backups.vbs';$run="wscript.exe //B //Nologo `"$vbs`" `"$RuntimeDir`"";$sc=if($Schedule-eq'daily'){'DAILY'}else{'WEEKLY'};schtasks.exe /Create /TN $task /TR $run /SC $sc /ST 03:00 /F|Out-Null;if($LASTEXITCODE-ne0){throw 'De back-uptaak kon niet worden ingesteld.'}
